{"content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>F1 Night Duel</title>
<style>
*, *::before, *::after {
  box-sizing: border-box;
}
html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: radial-gradient(circle at center, #161922 0%, #090a0f 100%);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  -webkit-user-select: none;
  user-select: none;
}
#stage {
  display: block;
  width: 100vw;
  height: 100vh;
}

#countdown {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 50;
  pointer-events: none;
  font-size: 96px;
  font-weight: 700;
  line-height: 1;
  color: rgba(255, 255, 255, 0.35);
  font-variant-numeric: tabular-nums;
}

#dock {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 100;
  width: 536px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 0 14px;
  background: rgba(15, 17, 23, 0.78);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 9999px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.35);
}

#dock button {
  font-family: inherit;
  line-height: 1;
  margin: 0;
  flex-shrink: 0;
  white-space: nowrap;
  appearance: none;
  -webkit-appearance: none;
}

.dock-sep {
  width: 1px;
  height: 18px;
  flex-shrink: 0;
  background: rgba(255, 255, 255, 0.12);
}

#btn-refire {
  width: 78px;
  height: 28px;
  padding: 0 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 9999px;
  color: #ffffff;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
}
#btn-refire:hover {
  background: rgba(255, 255, 255, 0.16);
}

#btn-toggle {
  width: 28px;
  height: 28px;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 9999px;
  color: #ffffff;
  cursor: pointer;
}
#btn-toggle:hover {
  background: rgba(255, 255, 255, 0.16);
}

#speed-group {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}
.speed-pill {
  width: 42px;
  height: 24px;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 9999px;
  color: rgba(255, 255, 255, 0.6);
  font-size: 11px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
}
.speed-pill:hover {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.06);
}
.speed-pill.is-active {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.18);
  border-color: rgba(255, 255, 255, 0.2);
}

#scrubber {
  width: 157px;
  height: 4px;
  margin: 0;
  padding: 0;
  flex-shrink: 0;
  appearance: none;
  -webkit-appearance: none;
  background: rgba(255, 255, 255, 0.22);
  border-radius: 9999px;
  outline: none;
  cursor: pointer;
}
#scrubber::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #ffffff;
  border: none;
  cursor: pointer;
}
#scrubber::-moz-range-thumb {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #ffffff;
  border: none;
  cursor: pointer;
}
</style>
</head>
<body>
<canvas id="stage"></canvas>
<div id="countdown" aria-hidden="true">3</div>

<div id="dock" role="toolbar" aria-label="Simulation Controls">
  <button id="btn-refire" type="button" aria-label="Re-fire" title="Re-fire">
    <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
      <path d="M21.5 2v6h-6M21.34 15.57a10 10 0 1 1-.57-8.38l5.67-5.19"/>
    </svg>
    <span>Re-fire</span>
  </button>
  <span class="dock-sep" aria-hidden="true"></span>
  <button id="btn-toggle" type="button" aria-label="Pause" title="Play / Pause">
    <svg id="icon-pause" viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden="true">
      <rect x="6" y="4" width="4" height="16" rx="1"/>
      <rect x="14" y="4" width="4" height="16" rx="1"/>
    </svg>
    <svg id="icon-play" viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden="true" style="display:none;">
      <path d="M8 5v14l11-7z"/>
    </svg>
  </button>
  <span class="dock-sep" aria-hidden="true"></span>
  <div id="speed-group" role="radiogroup" aria-label="Playback Speed">
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="0.25">0.25×</button>
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="0.5">0.5×</button>
    <button class="speed-pill is-active" type="button" role="radio" aria-checked="true" data-speed="1.0">1.0×</button>
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="2.0">2.0×</button>
  </div>
  <span class="dock-sep" aria-hidden="true"></span>
  <input id="scrubber" type="range" min="0" max="40" step="0.001" value="0" aria-label="Timeline Scrubber">
</div>

<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/three.min.js"></script>
<script>
'use strict';

const DURATION = 40;
const FINISH_S = 1551.65;
const TRACK_HALF = 7;
const SEED = 42;
const AUDIO_SEED = 4242;

function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
function smoothstep(a, b, x) {
  const t = clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}
function normalizeAngle(a) {
  while (a > Math.PI) a -= Math.PI * 2;
  while (a < -Math.PI) a += Math.PI * 2;
  return a;
}

function mulberry32(a) {
  return function() {
    a |= 0;
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const rng = mulberry32(SEED);
const audioRng = mulberry32(AUDIO_SEED);

const UP = new THREE.Vector3(0, 1, 0);

const canvas = document.getElementById('stage');
const renderer = new THREE.WebGLRenderer({
  canvas: canvas,
  antialias: true,
  alpha: true
});
renderer.outputEncoding = THREE.sRGBEncoding;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 0.9;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.setClearColor(0x05070d, 1);

const scene = new THREE.Scene();
scene.background = null;
scene.fog = new THREE.FogExp2(0x1a2230, 0.0022);

const camera = new THREE.PerspectiveCamera(35, 1, 0.1, 3000);
camera.position.set(-34, 2.6, 0);

const particleScaleUniform = { value: 1 };
const maxAniso = renderer.capabilities.getMaxAnisotropy();

let L = 0;
let N = 4000;
let frames = [];
let road = null;
let grandstand = null;
let grandstandCenter = new THREE.Vector3();
let gantryLensMats = [];
let particleFields = [];
let flashTimes = [];
let red = null;
let blue = null;

function initTrack() {
  const pts = [
    new THREE.Vector3(0, 0, 0),
    new THREE.Vector3(200, 0, 0),
    new THREE.Vector3(320, 5, 60),
    new THREE.Vector3(340, 12, 180),
    new THREE.Vector3(260, 20, 260),
    new THREE.Vector3(120, 15, 240),
    new THREE.Vector3(60, 8, 320),
    new THREE.Vector3(-80, 4, 340),
    new THREE.Vector3(-200, 0, 260),
    new THREE.Vector3(-240, 0, 120),
    new THREE.Vector3(-160, 0, 40),
    new THREE.Vector3(-80, 0, 0)
  ];
  const curve = new THREE.CatmullRomCurve3(pts, true, 'centripetal');
  curve.arcLengthDivisions = 4000;
  L = curve.getLength();
  N = 4000;
  frames = [];
  for (let i = 0; i < N; i++) {
    const u = i / N;
    const p = curve.getPointAt(u);
    const t = curve.getTangentAt(u).normalize();
    const n = new THREE.Vector3().crossVectors(t, UP).normalize();
    frames.push({ p: p, t: t, n: n });
  }
}

function frameAt(s) {
  let ss = ((s % L) + L) % L;
  const f = (ss / L) * N;
  const fi = Math.floor(f);
  const i = fi % N;
  const j = (i + 1) % N;
  const a = f - fi;
  const p = frames[i].p.clone().lerp(frames[j].p, a);
  const t = frames[i].t.clone().lerp(frames[j].t, a).normalize();
  const n = new THREE.Vector3().crossVectors(t, UP).normalize();
  return { p: p, t: t, n: n };
}

function makeCanvasTexture(w, h, draw, srgb) {
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  const ctx = c.getContext('2d');
  draw(ctx, w, h);
  const tex = new THREE.CanvasTexture(c);
  tex.anisotropy = maxAniso;
  if (srgb !== false) tex.encoding = THREE.sRGBEncoding;
  tex.needsUpdate = true;
  return tex;
}

function makeAsphaltTexture() {
  const tex = makeCanvasTexture(512, 512, (ctx, w, h) => {
    ctx.fillStyle = '#16191e';
    ctx.fillRect(0, 0, w, h);
    for (let i = 0; i < 9000; i++) {
      const x = rng() * w;
      const y = rng() * h;
      const v = 18 + rng() * 28;
      ctx.fillStyle = 'rgba(' + v + ',' + (v + 2) + ',' + (v + 5) + ',' + (0.08 + rng() * 0.18) + ')';
      ctx.fillRect(x, y, 1 + rng() * 2, 1 + rng() * 2);
    }
    for (let i = 0; i < 90; i++) {
      const x = rng() * w;
      const y = rng() * h;
      const len = 10 + rng() * 90;
      ctx.strokeStyle = 'rgba(8,9,11,' + (0.06 + rng() * 0.12) + ')';
      ctx.lineWidth = 1 + rng() * 2;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + len, y + (rng() - 0.5) * 4);
      ctx.stroke();
    }
  }, true);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  return tex;
}

function makeRoughnessTexture() {
  const tex = makeCanvasTexture(512, 512, (ctx, w, h) => {
    ctx.fillStyle = '#b4b4b4';
    ctx.fillRect(0, 0, w, h);
    for (let i = 0; i < 26; i++) {
      const x = rng() * w;
      const y = rng() * h;
      const r = 18 + rng() * 90;
      const g = ctx.createRadialGradient(x, y, 0, x, y, r);
      g.addColorStop(0, 'rgba(18,18,18,0.95)');
      g.addColorStop(0.65, 'rgba(90,90,90,0.35)');
      g.addColorStop(1, 'rgba(180,180,180,0)');
      ctx.fillStyle = g;
      ctx.fillRect(x - r, y - r, r * 2, r * 2);
    }
  }, false);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  return tex;
}

function makePoolTexture() {
  return makeCanvasTexture(256, 256, (ctx, w, h) => {
    const g = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
    g.addColorStop(0, 'rgba(255,255,255,1)');
    g.addColorStop(0.18, 'rgba(255,255,255,0.78)');
    g.addColorStop(0.55, 'rgba(255,255,255,0.22)');
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  }, true);
}

function makeFenceTexture() {
  const tex = makeCanvasTexture(128, 128, (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h);
    ctx.strokeStyle = 'rgba(180,192,208,0.9)';
    ctx.lineWidth = 1.2;
    for (let x = 0; x <= w; x += 12) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, h);
      ctx.stroke();
    }
    for (let y = 0; y <= h; y += 12) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(w, y);
      ctx.stroke();
    }
  }, true);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  return tex;
}

function makeCheckerTexture() {
  const tex = makeCanvasTexture(256, 64, (ctx, w, h) => {
    const cols = 16;
    const rows = 2;
    for (let y = 0; y < rows; y++) {
      for (let x = 0; x < cols; x++) {
        ctx.fillStyle = ((x + y) & 1) ? '#e9edf2' : '#111318';
        ctx.fillRect(x * w / cols, y * h / rows, w / cols + 1, h / rows + 1);
      }
    }
  }, true);
  return tex;
}

function makeGridBoxTexture() {
  return makeCanvasTexture(256, 512, (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h);
    ctx.strokeStyle = 'rgba(235,242,250,0.9)';
    ctx.lineWidth = 10;
    ctx.strokeRect(14, 14, w - 28, h - 28);
    ctx.lineWidth = 4;
    ctx.strokeStyle = 'rgba(235,242,250,0.45)';
    ctx.strokeRect(30, 30, w - 60, h - 60);
  }, true);
}

function makeCarbonTexture() {
  const tex = makeCanvasTexture(128, 128, (ctx, w, h) => {
    ctx.fillStyle = '#14171c';
    ctx.fillRect(0, 0, w, h);
    for (let i = -h; i < w + h; i += 8) {
      ctx.strokeStyle = i % 16 === 0 ? 'rgba(42,48,58,0.75)' : 'rgba(27,31,38,0.7)';
      ctx.lineWidth = 2.4;
      ctx.beginPath();
      ctx.moveTo(i, 0);
      ctx.lineTo(i + h, h);
      ctx.stroke();
      ctx.strokeStyle = 'rgba(10,12,16,0.8)';
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(i + 3, 0);
      ctx.lineTo(i + h + 3, h);
      ctx.stroke();
    }
  }, true);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(2, 2);
  return tex;
}

function makeLiveryTexture(number, accentColor, isBlue) {
  return makeCanvasTexture(256, 512, (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = accentColor;
    ctx.fillRect(24, 0, 38, h);
    ctx.fillStyle = isBlue ? '#d8e0ee' : '#ffffff';
    ctx.font = 'bold 214px Arial, Helvetica, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(number, w / 2 + 14, h / 2 + 8);
  }, true);
}

function makeNumberTexture(number, accentColor) {
  return makeCanvasTexture(256, 256, (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = accentColor;
    ctx.font = 'bold 180px Arial, Helvetica, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(number, w / 2, h / 2 + 6);
  }, true);
}

const asphaltTex = makeAsphaltTexture();
const roughTex = makeRoughnessTexture();
const poolTex = makePoolTexture();
const fenceTex = makeFenceTexture();
const checkerTex = makeCheckerTexture();
const gridBoxTex = makeGridBoxTexture();
const carbonTex = makeCarbonTexture();

function createSky() {
  const skyMat = new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0 },
      uMoonDir: { value: new THREE.Vector3(-0.34, 0.42, -0.84).normalize() }
    },
    vertexShader: `
      varying vec3 vWorld;
      void main() {
        vWorld = (modelMatrix * vec4(position, 1.0)).xyz;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      uniform float uTime;
      uniform vec3 uMoonDir;
      varying vec3 vWorld;

      float hash(vec2 p) {
        return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
      }

      void main() {
        vec3 dir = normalize(vWorld);
        float h = clamp(dir.y, -0.1, 1.0);
        vec3 sky = mix(vec3(0.016, 0.026, 0.052), vec3(0.002, 0.004, 0.012), smoothstep(0.0, 0.62, h));
        float horizon = pow(1.0 - clamp(h, 0.0, 1.0), 6.0);
        float citySide = smoothstep(0.15, 0.9, dot(normalize(vec3(dir.x, 0.0, dir.z)), normalize(vec3(0.78, 0.0, 0.62))));
        sky += vec3(0.32, 0.14, 0.05) * horizon * citySide * 0.32;

        vec2 sp = vec2(atan(dir.z, dir.x), asin(clamp(dir.y, -1.0, 1.0)));
        vec2 grid = floor(sp * 340.0);
        float n = hash(grid);
        float star = smoothstep(0.9972, 1.0, n) * smoothstep(0.0, 0.12, dir.y);
        float tw = 0.65 + 0.35 * sin(uTime * 2.0 + n * 50.0);
        sky += vec3(0.95, 0.96, 1.0) * star * 0.72 * tw;

        float md = max(dot(dir, uMoonDir), 0.0);
        sky += vec3(0.72, 0.82, 1.0) * pow(md, 900.0) * 1.8;
        sky += vec3(0.16, 0.22, 0.34) * pow(md, 24.0) * 0.22;

        gl_FragColor = vec4(sky, 1.0);
      }
    `,
    side: THREE.BackSide,
    depthWrite: false,
    depthTest: true,
    fog: false
  });
  const sky = new THREE.Mesh(new THREE.SphereGeometry(2500, 32, 16), skyMat);
  sky.frustumCulled = false;
  sky.renderOrder = -10;
  scene.add(sky);
  return skyMat;
}

const skyMat = createSky();

function createEnvironmentMap() {
  const envScene = new THREE.Scene();
  envScene.background = new THREE.Color(0x05070d);
  const panelGeo = new THREE.PlaneGeometry(8, 4);
  const panelMat = new THREE.MeshBasicMaterial({ color: 0xdce9ff, side: THREE.DoubleSide });
  const warmMat = new THREE.MeshBasicMaterial({ color: 0xffd9a0, side: THREE.DoubleSide });
  const positions = [
    [10, 9, 0], [-10, 9, 0], [0, 9, 10], [0, 9, -10],
    [0, 22, 0], [7, 18, 7], [-7, 18, -7]
  ];
  for (let i = 0; i < positions.length; i++) {
    const m = new THREE.Mesh(panelGeo, i > 3 ? warmMat : panelMat);
    m.position.set(positions[i][0], positions[i][1], positions[i][2]);
    m.lookAt(0, 0, 0);
    envScene.add(m);
  }
  const pmrem = new THREE.PMREMGenerator(renderer);
  const rt = pmrem.fromScene(envScene, 0.04);
  pmrem.dispose();
  return rt.texture;
}

scene.environment = createEnvironmentMap();

let spot1 = null;
let spot2 = null;
function createLights() {
  const ambient = new THREE.AmbientLight(0x223355, 0.12);
  scene.add(ambient);
  const moon = new THREE.DirectionalLight(0x9bb8ff, 0.08);
  moon.position.set(-110, 150, -60);
  scene.add(moon);

  spot1 = new THREE.SpotLight(0xcfe0ff, 2.0, 80, 0.56, 0.8, 1.2);
  spot1.position.set(20, 30, 20);
  spot1.castShadow = true;
  spot1.shadow.mapSize.set(1024, 1024);
  spot1.shadow.camera.near = 1;
  spot1.shadow.camera.far = 100;
  spot1.shadow.bias = -0.0005;
  scene.add(spot1);
  scene.add(spot1.target);

  spot2 = new THREE.SpotLight(0xbfd0ff, 1.0, 80, 0.62, 0.8, 1.2);
  spot2.position.set(-20, 25, -15);
  scene.add(spot2);
  scene.add(spot2.target);
}
createLights();

function buildRibbon(dCenter, width, material, yOff, segments) {
  const seg = segments || 1600;
  const pos = [];
  const uv = [];
  const idx = [];
  for (let i = 0; i <= seg; i++) {
    const s = (i / seg) * L;
    const f = frameAt(s);
    const a = f.p.clone().addScaledVector(f.n, dCenter - width / 2);
    const b = f.p.clone().addScaledVector(f.n, dCenter + width / 2);
    a.y += yOff;
    b.y += yOff;
    pos.push(a.x, a.y, a.z, b.x, b.y, b.z);
    const u = s / 8;
    uv.push(u, 0, u, 1);
  }
  for (let i = 0; i < seg; i++) {
    const a = i * 2;
    const b = a + 1;
    const c = a + 2;
    const d = a + 3;
    idx.push(a, b, c, b, d, c);
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  geo.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  geo.setIndex(idx);
  geo.computeVertexNormals();
  const mesh = new THREE.Mesh(geo, material);
  scene.add(mesh);
  return mesh;
}

function makeQuad(s, dCenter, width, length, yOff, material) {
  const f = frameAt(s);
  const p0 = f.p.clone().addScaledVector(f.n, dCenter - width / 2).addScaledVector(f.t, -length / 2);
  const p1 = f.p.clone().addScaledVector(f.n, dCenter + width / 2).addScaledVector(f.t, -length / 2);
  const p2 = f.p.clone().addScaledVector(f.n, dCenter + width / 2).addScaledVector(f.t, length / 2);
  const p3 = f.p.clone().addScaledVector(f.n, dCenter - width / 2).addScaledVector(f.t, length / 2);
  p0.y += yOff; p1.y += yOff; p2.y += yOff; p3.y += yOff;
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute([
    p0.x, p0.y, p0.z,
    p1.x, p1.y, p1.z,
    p2.x, p2.y, p2.z,
    p3.x, p3.y, p3.z
  ], 3));
  geo.setAttribute('uv', new THREE.Float32BufferAttribute([0, 0, 1, 0, 1, 1, 0, 1], 2));
  geo.setIndex([0, 1, 2, 0, 2, 3]);
  geo.computeVertexNormals();
  const mesh = new THREE.Mesh(geo, material);
  mesh.receiveShadow = true;
  scene.add(mesh);
  return mesh;
}

