function createKerbs() {
  const pos = [];
  const col = [];
  const idx = [];
  const red = new THREE.Color(0xd21f2b);
  const white = new THREE.Color(0xe8e8e8);
  let vi = 0;
  for (let i = 0; i < N; i++) {
    const s = (i / N) * L;
    const f0 = frames[i];
    const f1 = frames[(i + 1) % N];
    const cross = f0.t.x * f1.t.z - f0.t.z * f1.t.x;
    const dot = clamp(f0.t.x * f1.t.x + f0.t.z * f1.t.z, -1, 1);
    const ang = Math.abs(Math.atan2(cross, dot));
    if (ang > 0.0012) {
      const color = (Math.floor(s / 3) & 1) ? white : red;
      for (let side = -1; side <= 1; side += 2) {
        const d0 = side * 6.9;
        const d1 = side * 7.8;
        const a = f0.p.clone().addScaledVector(f0.n, d0);
        const b = f0.p.clone().addScaledVector(f0.n, d1);
        const c = f1.p.clone().addScaledVector(f1.n, d1);
        const d = f1.p.clone().addScaledVector(f1.n, d0);
        a.y += 0.045; b.y += 0.045; c.y += 0.045; d.y += 0.045;
        pos.push(a.x, a.y, a.z, b.x, b.y, b.z, c.x, c.y, c.z, d.x, d.y, d.z);
        for (let k = 0; k < 4; k++) col.push(color.r, color.g, color.b);
        idx.push(vi, vi + 1, vi + 2, vi, vi + 2, vi + 3);
        vi += 4;
      }
    }
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  geo.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  geo.setIndex(idx);
  geo.computeVertexNormals();
  const mat = new THREE.MeshStandardMaterial({
    vertexColors: true,
    roughness: 0.62,
    metalness: 0.1,
    side: THREE.DoubleSide
  });
  scene.add(new THREE.Mesh(geo, mat));
}

function buildBarrier(side) {
  const N2 = 2000;
  const pos = [];
  const col = [];
  const idx = [];
  const cLight = new THREE.Color(0xb8c0c8);
  const cDark = new THREE.Color(0x8a1020);
  for (let i = 0; i <= N2; i++) {
    const s = (i / N2) * L;
    const f = frameAt(s);
    const base = f.p.clone().addScaledVector(f.n, side * 9);
    base.y += 0.02;
    const top = base.clone();
    top.y += 1.1;
    const color = (Math.floor(s / 8) & 1) ? cDark : cLight;
    pos.push(base.x, base.y, base.z, top.x, top.y, top.z);
    col.push(color.r, color.g, color.b, color.r, color.g, color.b);
  }
  for (let i = 0; i < N2; i++) {
    const a = i * 2;
    const b = a + 1;
    const c = a + 2;
    const d = a + 3;
    idx.push(a, b, c, b, d, c);
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  geo.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  geo.setIndex(idx);
  geo.computeVertexNormals();
  const mat = new THREE.MeshStandardMaterial({
    vertexColors: true,
    roughness: 0.6,
    metalness: 0.18,
    side: THREE.DoubleSide
  });
  scene.add(new THREE.Mesh(geo, mat));

  const fpos = [];
  const fuv = [];
  const fidx = [];
  for (let i = 0; i <= N2; i++) {
    const s = (i / N2) * L;
    const f = frameAt(s);
    const base = f.p.clone().addScaledVector(f.n, side * 9.2);
    const y0 = base.y + 1.1;
    const y1 = base.y + 4.5;
    fpos.push(base.x, y0, base.z, base.x, y1, base.z);
    const u = s / 4;
    fuv.push(u, 0, u, 1);
  }
  for (let i = 0; i < N2; i++) {
    const a = i * 2;
    const b = a + 1;
    const c = a + 2;
    const d = a + 3;
    fidx.push(a, b, c, b, d, c);
  }
  const fgeo = new THREE.BufferGeometry();
  fgeo.setAttribute('position', new THREE.Float32BufferAttribute(fpos, 3));
  fgeo.setAttribute('uv', new THREE.Float32BufferAttribute(fuv, 2));
  fgeo.setIndex(fidx);
  fgeo.computeVertexNormals();
  const fenceMat = new THREE.MeshBasicMaterial({
    map: fenceTex,
    color: 0x9aa4b2,
    transparent: true,
    opacity: 0.42,
    side: THREE.DoubleSide,
    depthWrite: false
  });
  scene.add(new THREE.Mesh(fgeo, fenceMat));
}

function createBarriers() {
  buildBarrier(-1);
  buildBarrier(1);
  const postGeo = new THREE.BoxGeometry(0.08, 3.4, 0.08);
  const postMat = new THREE.MeshStandardMaterial({ color: 0x6b7480, metalness: 0.8, roughness: 0.42 });
  const count = Math.ceil(L / 10) * 2;
  const inst = new THREE.InstancedMesh(postGeo, postMat, count);
  const dummy = new THREE.Object3D();
  let idx = 0;
  for (let side = -1; side <= 1; side += 2) {
    for (let s = 0; s < L; s += 10) {
      const f = frameAt(s);
      dummy.position.copy(f.p).addScaledVector(f.n, side * 9.2);
      dummy.position.y += 2.8;
      dummy.rotation.set(0, 0, 0);
      dummy.updateMatrix();
      inst.setMatrixAt(idx++, dummy.matrix);
    }
  }
  inst.count = idx;
  inst.instanceMatrix.needsUpdate = true;
  scene.add(inst);
}

function createTerrain() {
  const terrainMat = new THREE.MeshStandardMaterial({
    color: 0x0a0f12,
    roughness: 1,
    metalness: 0,
    side: THREE.DoubleSide
  });
  const laterals = [8, 14, 24, 40, 70, 120, 180];
  const seg = 600;
  for (let side = -1; side <= 1; side += 2) {
    const pos = [];
    const idx = [];
    for (let i = 0; i <= seg; i++) {
      const s = (i / seg) * L;
      const f = frameAt(s);
      for (let j = 0; j < laterals.length; j++) {
        const lat = laterals[j];
        const p = f.p.clone().addScaledVector(f.n, side * lat);
        let y = f.p.y - 0.35 + Math.pow(lat / 180, 1.4) * 7;
        y += Math.sin(s * 0.013 + lat * 0.07) * 1.2;
        y += Math.sin(s * 0.031 - lat * 0.02) * 0.8;
        p.y = y;
        pos.push(p.x, p.y, p.z);
      }
    }
    const cols = laterals.length;
    for (let i = 0; i < seg; i++) {
      for (let j = 0; j < cols - 1; j++) {
        const a = i * cols + j;
        const b = a + 1;
        const c = a + cols;
        const d = c + 1;
        idx.push(a, c, b, b, c, d);
      }
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    geo.setIndex(idx);
    geo.computeVertexNormals();
    scene.add(new THREE.Mesh(geo, terrainMat));
  }
  const base = new THREE.Mesh(
    new THREE.PlaneGeometry(3000, 3000, 1, 1),
    new THREE.MeshStandardMaterial({ color: 0x06080b, roughness: 1 })
  );
  base.rotation.x = -Math.PI / 2;
  base.position.y = -6;
  scene.add(base);

  const hillMat = new THREE.MeshStandardMaterial({ color: 0x0b1015, roughness: 1 });
  const hillData = [
    [-420, 430, 150, 45], [520, 420, 180, 55], [620, -80, 130, 40],
    [-520, -160, 160, 50], [180, 560, 140, 38], [-260, -420, 120, 34]
  ];
  for (let i = 0; i < hillData.length; i++) {
    const d = hillData[i];
    const hill = new THREE.Mesh(new THREE.ConeGeometry(d[2], d[3], 8), hillMat);
    hill.position.set(d[0], d[3] / 2 - 6, d[1]);
    scene.add(hill);
  }
}

