    const side = (i & 1) ? -1 : 1;
    const f = frameAt(s);
    const base = f.p.clone().addScaledVector(f.n, side * 11.5);
    base.y = f.p.y - 0.2;

    const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.28, 30, 8), poleMat);
    pole.position.copy(base).add(new THREE.Vector3(0, 15, 0));
