    const head = new THREE.Mesh(new THREE.BoxGeometry(2.4, 0.5, 0.6), lampMat);
    head.position.copy(base).add(new THREE.Vector3(0, 30.2, 0));
    head.rotation.y = Math.atan2(f.t.x, f.t.z);
    scene.add(head);

    const cone = new THREE.Mesh(new THREE.ConeGeometry(10, 30, 16, 1, true), coneMat);
    cone.position.copy(base).add(new THREE.Vector3(0, 15, 0));
