function trackGroup(s, d, yOff) {
  const f = frameAt(s);
  const g = new THREE.Group();
  g.position.copy(f.p).addScaledVector(f.n, d);
  g.position.y += (yOff || 0);
  g.rotation.y = Math.atan2(f.t.x, f.t.z);
  return g;
}

function addBox(parent, w, h, d, x, y, z, mat, rx, ry, rz) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  m.position.set(x, y, z);
  m.rotation.set(rx || 0, ry || 0, rz || 0);
  m.castShadow = true;
  parent.add(m);
  return m;
}

function taperedBoxGeometry(z0, z1, w0, h0, w1, h1, y0, y1) {
  const hw0 = w0 / 2, hh0 = h0 / 2;
  const hw1 = w1 / 2, hh1 = h1 / 2;
  const pos = [
    -hw0, y0 - hh0, z0,
     hw0, y0 - hh0, z0,
     hw0, y0 + hh0, z0,
    -hw0, y0 + hh0, z0,
    -hw1, y1 - hh1, z1,
     hw1, y1 - hh1, z1,
     hw1, y1 + hh1, z1,
    -hw1, y1 + hh1, z1
  ];
  const uv = [];
  for (let i = 0; i < 8; i++) uv.push((pos[i * 3] + 1) * 0.5, (pos[i * 3 + 2] + 3) / 6);
  const idx = [
    0, 2, 1, 0, 3, 2,
    4, 5, 6, 4, 6, 7,
    0, 1, 5, 0, 5, 4,
    3, 7, 6, 3, 6, 2,
    0, 4, 7, 0, 7, 3,
    1, 2, 6, 1, 6, 5
  ];
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  geo.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  geo.setIndex(idx);
  geo.computeVertexNormals();
  return geo;
}

function addTapered(parent, z0, z1, w0, h0, w1, h1, y0, y1, mat) {
  const m = new THREE.Mesh(taperedBoxGeometry(z0, z1, w0, h0, w1, h1, y0, y1), mat);
  m.castShadow = true;
  parent.add(m);
  return m;
}

function tubeBetween(a, b, r, mat, parent) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  const geo = new THREE.CylinderGeometry(r, r, len, 6);
  const m = new THREE.Mesh(geo, mat);
  m.position.copy(a).add(b).multiplyScalar(0.5);
  m.quaternion.setFromUnitVectors(UP, dir.normalize());
  m.castShadow = true;
  parent.add(m);
  return m;
}

function createWheel(car, x, z, isFront, side) {
  const wheelGroup = new THREE.Group();
  wheelGroup.position.set(x, 0.36, z);
  car.group.add(wheelGroup);

  const spin = new THREE.Group();
  wheelGroup.add(spin);

  const width = isFront ? 0.31 : 0.40;
  const tireMat = new THREE.MeshStandardMaterial({ color: 0x070809, roughness: 0.92, metalness: 0 });
  const sidewallMat = new THREE.MeshStandardMaterial({ color: 0x050506, roughness: 0.9, side: THREE.DoubleSide });
  const rimMat = new THREE.MeshStandardMaterial({ color: 0xaeb7c4, roughness: 0.25, metalness: 0.9 });
  const brakeMat = car.brakeMat;
  const stripeMat = car.accentMat;

  const tire = new THREE.Mesh(new THREE.CylinderGeometry(0.36, 0.36, width, 24, 1, true), tireMat);
  tire.rotation.z = Math.PI / 2;
  tire.castShadow = true;
  spin.add(tire);

  for (let s = -1; s <= 1; s += 2) {
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.22, 0.36, 24), sidewallMat);
    ring.rotation.y = s > 0 ? Math.PI / 2 : -Math.PI / 2;
    ring.position.x = s * width / 2;
    spin.add(ring);

    const stripe = new THREE.Mesh(new THREE.TorusGeometry(0.30, 0.008, 6, 24), stripeMat);
    stripe.rotation.y = Math.PI / 2;
    stripe.position.x = s * (width / 2 + 0.006);
    spin.add(stripe);
  }

  const rim = new THREE.Mesh(new THREE.TorusGeometry(0.22, 0.018, 8, 24), rimMat);
  rim.rotation.y = Math.PI / 2;
  spin.add(rim);

  for (let i = 0; i < 5; i++) {
    const spoke = new THREE.Mesh(new THREE.BoxGeometry(0.018, 0.40, 0.025), rimMat);
    spoke.rotation.x = i * Math.PI * 2 / 5;
    spin.add(spoke);
  }

  const disc = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.18, 0.025, 24), brakeMat);
  disc.rotation.z = Math.PI / 2;
  spin.add(disc);

  const nut = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.045, 0.05, 8), rimMat);
  nut.rotation.z = Math.PI / 2;
  nut.position.x = side * (width / 2 + 0.02);
  spin.add(nut);

  const wheel = { group: wheelGroup, spin: spin, isFront: isFront, side: side };
  car.wheels.push(wheel);
  if (isFront) car.frontWheels.push(wheel);
  else car.rearWheels.push(wheel);
  return wheel;
}

function createCar(index, paintHex, accentHex, number, isBlue) {
  const group = new THREE.Group();
  group.rotation.order = 'YXZ';
  const body = new THREE.Group();
  group.add(body);

  const paint = new THREE.MeshPhysicalMaterial({
