  const mono = addTapered(body, -0.75, 1.5, 0.55, 0.38, 0.72, 0.35, 0.33, 0.30, paint);
  mono.castShadow = true;
  addBox(body, 1.05, 0.06, 3.6, 0, 0.03, 0, carbon);
  addBox(body, 0.06, 0.12, 3.3, -0.55, 0.08, 0, carbon);
  addBox(body, 0.06, 0.12, 3.3, 0.55, 0.08, 0, carbon);
  addBox(body, 0.9, 0.16, 0.5, 0, 0.10, -2.25, carbon);
  for (let i = 0; i < 5; i++) {
    addBox(body, 0.02, 0.18, 0.5, -0.32 + i * 0.16, 0.08, -2.25, carbon);
