  addTapered(body, 1.4, 2.62, 0.34, 0.20, 0.16, 0.12, 0.31, 0.24, paint);
  addBox(body, 0.18, 0.10, 0.18, 0, 0.24, 2.68, paint);
  addBox(body, 0.55, 0.03, 0.9, 0, 0.52, 0.30, new THREE.MeshStandardMaterial({ color: 0x08090c, roughness: 0.9 }));

  const cockpitRim = new THREE.Mesh(new THREE.TorusGeometry(0.32, 0.018, 8, 24), carbon);
  cockpitRim.rotation.x = Math.PI / 2;
  cockpitRim.scale.set(1.2, 1.5, 1);
  cockpitRim.position.set(0, 0.55, 0.25);
  body.add(cockpitRim);

  const haloCurve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(-0.35, 0.62, 0.0),
    new THREE.Vector3(-0.30, 0.82, 0.25),
