function makePchip(xs, ys) {
  const n = xs.length;
  const h = new Array(n - 1);
  const delta = new Array(n - 1);
  for (let i = 0; i < n - 1; i++) {
    h[i] = xs[i + 1] - xs[i];
    delta[i] = (ys[i + 1] - ys[i]) / h[i];
  }
  const m = new Array(n).fill(0);
  m[0] = delta[0];
  m[n - 1] = delta[n - 2];
  for (let i = 1; i < n - 1; i++) {
    if (delta[i - 1] * delta[i] <= 0) {
      m[i] = 0;
    } else {
      const w1 = 2 * h[i] + h[i - 1];
      const w2 = h[i] + 2 * h[i - 1];
      m[i] = (w1 + w2) / (w1 / delta[i - 1] + w2 / delta[i]);
    }
  }
  return { xs: xs, ys: ys, h: h, m: m, n: n };
}

function pchipEval(p, t) {
  const xs = p.xs;
  const ys = p.ys;
  const m = p.m;
  if (t <= xs[0]) return { v: ys[0], d1: 0, d2: 0 };
  if (t >= xs[p.n - 1]) return { v: ys[p.n - 1], d1: m[p.n - 1], d2: 0 };
  let lo = 0;
  let hi = p.n - 1;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (xs[mid] <= t) lo = mid;
    else hi = mid;
  }
  const hh = p.h[lo];
  const s = (t - xs[lo]) / hh;
  const s2 = s * s;
  const s3 = s2 * s;
  const h00 = 2 * s3 - 3 * s2 + 1;
  const h10 = s3 - 2 * s2 + s;
  const h01 = -2 * s3 + 3 * s2;
  const h11 = s3 - s2;
  const v = h00 * ys[lo] + h10 * hh * m[lo] + h01 * ys[lo + 1] + h11 * hh * m[lo + 1];
  const d1 = ((6 * s2 - 6 * s) * ys[lo] + (3 * s2 - 4 * s + 1) * hh * m[lo] + (-6 * s2 + 6 * s) * ys[lo + 1] + (3 * s2 - 2 * s) * hh * m[lo + 1]) / hh;
  const d2 = ((12 * s - 6) * ys[lo] + (6 * s - 4) * hh * m[lo] + (-12 * s + 6) * ys[lo + 1] + (6 * s - 2) * hh * m[lo + 1]) / (hh * hh);
  return { v: v, d1: d1, d2: d2 };
}

function getCarPositionAt(car, t) {
  const s = pchipEval(car.sCurve, t).v;
  const d = pchipEval(car.dCurve, t).v;
  const f = frameAt(s);
  return f.p.clone().addScaledVector(f.n, d);
}

function getCarState(car, t) {
  const sp = pchipEval(car.sCurve, t);
  const dp = pchipEval(car.dCurve, t);
  const s = sp.v;
  const d = dp.v;
  const speed = sp.d1;
  const accel = sp.d2;
  const latSpeed = dp.d1;
  const f = frameAt(s);
  const pos = f.p.clone().addScaledVector(f.n, d);

  const t1 = Math.max(0, t - 0.05);
  const t2 = Math.min(DURATION, t + 0.05);
  const p1 = getCarPositionAt(car, t1);
  const p2 = getCarPositionAt(car, t2);
  let forward = p2.clone().sub(p1);
  if (forward.lengthSq() < 1e-6) forward.copy(f.t);
  forward.normalize();

  const yaw = Math.atan2(forward.x, forward.z);
  const pitch = -Math.asin(clamp(forward.y, -1, 1));

  const fAhead = frameAt(s + 1.0);
  const dyaw = normalizeAngle(Math.atan2(fAhead.t.x, fAhead.t.z) - Math.atan2(f.t.x, f.t.z));
  const latAcc = speed * speed * dyaw;

  return {
    s: s,
    d: d,
    speed: speed,
    accel: accel,
    latSpeed: latSpeed,
    pos: pos,
    forward: forward,
    yaw: yaw,
    pitch: pitch,
    latAcc: latAcc,
    frame: f
  };
}

function updateCarVisual(car, st, t) {
  car.group.position.copy(st.pos);
  car.group.rotation.order = 'YXZ';
  car.group.rotation.set(st.pitch, st.yaw, 0);

  const bodyPitch = clamp(-st.accel * 0.0022, -0.06, 0.06);
  const bodyRoll = clamp(-st.latAcc * 0.0009, -0.05, 0.05);
  car.bodyPivot.rotation.x = bodyPitch;
  car.bodyPivot.rotation.z = bodyRoll;

  const fNow = frameAt(st.s);
  const fAhead = frameAt(st.s + 2.0);
  const dyaw = normalizeAngle(Math.atan2(fAhead.t.x, fAhead.t.z) - Math.atan2(fNow.t.x, fNow.t.z));
  const steer = clamp(dyaw * 2.0, -0.35, 0.35);
  const spin = st.s / 0.36;

  for (let i = 0; i < car.frontWheels.length; i++) {
    car.frontWheels[i].group.rotation.y = steer;
    car.frontWheels[i].spin.rotation.x = spin;
  }
  for (let i = 0; i < car.rearWheels.length; i++) {
    car.rearWheels[i].spin.rotation.x = spin;
  }

  let drs = 0;
  if (car.isBlue && t >= 33.5 && t < 36.49) drs = Math.min(1, (t - 33.5) / 0.12);
  car.drsPivot.rotation.x = -drs * 0.5;

  const decel = Math.max(0, -st.accel);
  car.brakeMat.emissiveIntensity = clamp(decel / 25, 0, 1) * 3.0;

  const blink = Math.sin(t * Math.PI * 2 * 4) > 0 ? 3 : 0.1;
  car.rainMat.emissiveIntensity = blink;
}

