function updateCamera(t, redState, blueState, mid) {
  let pos;
  let target;
  let fov;

  if (t < 5) {
    pos = new THREE.Vector3(-34, 2.6, 0);
    target = new THREE.Vector3(0, 3.0, 0);
    fov = 35;
  } else if (t < 11) {
    const sB = blueState.s;
    const dB = blueState.d;
    const fBack = frameAt(sB - 9);
    const nB = frameAt(sB).n;
    pos = fBack.p.clone().addScaledVector(nB, dB).add(new THREE.Vector3(0, 2.4, 0));
    const fAhead = frameAt(sB + 14);
    target = fAhead.p.clone().add(new THREE.Vector3(0, 0.9, 0));
    fov = 50;
  } else if (t < 15) {
    const f = frameAt(400);
    pos = f.p.clone().addScaledVector(f.n, -18).add(new THREE.Vector3(0, 5, 0));
    target = mid.clone();
    fov = 24;
  } else if (t < 20) {
    const st = blueState;
    const q = new THREE.Quaternion().setFromEuler(new THREE.Euler(st.pitch, st.yaw, 0, 'YXZ'));
    const local = new THREE.Vector3(0, 1.25, -0.55).applyQuaternion(q);
    pos = st.pos.clone().add(local);
    const fAhead = frameAt(st.s + 40);
    target = fAhead.p.clone().addScaledVector(fAhead.n, st.d);
    target.y += 0.6;
    fov = 75;
  } else if (t < 24) {
    const f = frameAt(725);
    pos = f.p.clone().addScaledVector(f.n, 20).add(new THREE.Vector3(0, 3, 0));
    target = mid.clone();
    fov = 28;
  } else if (t < 30) {
    pos = new THREE.Vector3(-80, 120, 150);
    target = mid.clone();
    fov = 30;
  } else if (t < 34) {
    const f = frameAt(1300);
    pos = f.p.clone().addScaledVector(f.n, -12).add(new THREE.Vector3(0, 1.2, 0));
    target = mid.clone();
    fov = 30;
  } else {
    pos = new THREE.Vector3(-20, 4.5, 15);
    target = mid.clone();
    fov = 32;
  }

  camera.position.copy(pos);
  camera.fov = fov;
  camera.updateProjectionMatrix();
  camera.lookAt(target);
}

