function makeParticleField(count, blending) {
  const positions = new Float32Array(count * 3);
  const sizes = new Float32Array(count);
  const alphas = new Float32Array(count);
  const colors = new Float32Array(count * 3);
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geo.setAttribute('aSize', new THREE.BufferAttribute(sizes, 1));
  geo.setAttribute('aAlpha', new THREE.BufferAttribute(alphas, 1));
  geo.setAttribute('aColor', new THREE.BufferAttribute(colors, 3));

  const mat = new THREE.ShaderMaterial({
    uniforms: { uScale: particleScaleUniform },
    vertexShader: `
      uniform float uScale;
      attribute float aSize;
      attribute float aAlpha;
      attribute vec3 aColor;
      varying float vAlpha;
      varying vec3 vColor;
      void main() {
        vec4 mv = modelViewMatrix * vec4(position, 1.0);
        gl_PointSize = clamp(aSize * (uScale / max(-mv.z, 0.1)), 0.0, 220.0);
        gl_Position = projectionMatrix * mv;
        vAlpha = aAlpha;
        vColor = aColor;
      }
    `,
    fragmentShader: `
      varying float vAlpha;
      varying vec3 vColor;
      void main() {
        vec2 c = gl_PointCoord - vec2(0.5);
        float d = length(c);
        if (d > 0.5) discard;
        float a = smoothstep(0.5, 0.0, d) * vAlpha;
        gl_FragColor = vec4(vColor, a);
      }
    `,
    transparent: true,
    depthWrite: false,
    depthTest: true,
    blending: blending
  });

  const points = new THREE.Points(geo, mat);
  points.frustumCulled = false;
  points.renderOrder = 5;
  scene.add(points);
  return {
    points: points,
    geo: geo,
    positions: positions,
    sizes: sizes,
    alphas: alphas,
    colors: colors,
    particles: new Array(count),
    count: count
  };
}

function makeCarParticleField(car, type, count) {
  let blending = THREE.AdditiveBlending;
  if (type === 'smoke' || type === 'puff') blending = THREE.NormalBlending;
  const field = makeParticleField(count, blending);

  for (let i = 0; i < count; i++) {
    let t0;
    let local;
    let vel;
    let life;
    let size;
    let alpha;
    let gravity;
    let grow;
    let color;

    if (type === 'spray') {
      t0 = 3 + rng() * 37;
      const side = rng() < 0.5 ? -1 : 1;
      local = new THREE.Vector3(side * 0.85 + (rng() - 0.5) * 0.2, 0.04 + rng() * 0.10, -1.8 + (rng() - 0.5) * 0.4);
      vel = new THREE.Vector3((rng() - 0.5) * 2.5, 1.0 + rng() * 2.0, -3.0 - rng() * 4.0);
      life = 0.5 + rng() * 0.9;
      size = 0.08 + rng() * 0.12;
      alpha = 0.25 + rng() * 0.2;
      gravity = -9.8;
      grow = 1.5;
      color = new THREE.Color(0.62, 0.78, 1.0);
      const st0 = getCarState(car, t0);
      if (st0.speed < 5) alpha = 0;
    } else if (type === 'smoke') {
      t0 = i < count * 0.5 ? 3 + rng() * 3.5 : 18 + rng() * 8;
      local = new THREE.Vector3((rng() - 0.5) * 1.6, 0.05 + rng() * 0.1, -1.8 + (rng() - 0.5) * 0.5);
      vel = new THREE.Vector3((rng() - 0.5) * 1.2, 0.5 + rng() * 1.5, -1.0 - rng() * 3.0);
      life = 1.0 + rng() * 1.2;
      size = 0.35 + rng() * 0.7;
      alpha = 0.12 + rng() * 0.12;
      gravity = -0.5;
      grow = 2.0;
      color = new THREE.Color(0.42, 0.46, 0.52);
      const st0 = getCarState(car, t0);
      if (!(st0.speed > 5 && (t0 < 6.5 || st0.accel < -8 || (t0 > 19 && t0 < 24)))) alpha = 0;
    } else if (type === 'sparks') {
      t0 = rng() * 40;
      local = new THREE.Vector3((rng() - 0.5) * 1.2, 0.02, (rng() - 0.5) * 4.0);
      vel = new THREE.Vector3((rng() - 0.5) * 3.0, 1.0 + rng() * 4.0, -3.0 - rng() * 5.0);
      life = 0.2 + rng() * 0.4;
      size = 0.03 + rng() * 0.05;
      alpha = 0.8;
      gravity = -9.8;
      grow = 0;
      color = new THREE.Color(1.0, 0.52 + rng() * 0.2, 0.12);
      const st0 = getCarState(car, t0);
      if (!(st0.speed > 55.6 || st0.accel < -12)) alpha = 0;
    } else if (type === 'shimmer') {
      t0 = rng() * 40;
      local = new THREE.Vector3((rng() - 0.5) * 0.4, 0.2, -2.5);
      vel = new THREE.Vector3((rng() - 0.5) * 0.3, 0.5 + rng() * 1.5, -0.5 - rng() * 1.5);
      life = 0.3 + rng() * 0.4;
      size = 0.15 + rng() * 0.2;
      alpha = 0.05;
      gravity = -0.2;
      grow = 1.5;
      color = new THREE.Color(0.35, 0.42, 0.52);
      const st0 = getCarState(car, t0);
      if (st0.speed < 1) alpha = 0;
    } else {
      t0 = 20.5 + rng() * 2.0;
      local = new THREE.Vector3(-0.7 + (rng() - 0.5) * 0.3, 0.05, 1.8 + (rng() - 0.5) * 0.3);
      vel = new THREE.Vector3(-1.0 + rng() * 0.8, 0.8 + rng() * 1.5, -1.0 - rng() * 2.0);
      life = 0.6 + rng() * 0.8;
      size = 0.3 + rng() * 0.5;
      alpha = 0.15;
      gravity = -0.8;
      grow = 1.5;
      color = new THREE.Color(0.48, 0.50, 0.52);
    }

    const st = getCarState(car, t0);
    const q = new THREE.Quaternion().setFromEuler(new THREE.Euler(st.pitch, st.yaw, 0, 'YXZ'));
    const emit = st.pos.clone().add(local.clone().applyQuaternion(q));
    const worldVel = vel.clone().applyQuaternion(q);

    field.particles[i] = {
      t0: t0,
      x: emit.x,
      y: emit.y,
      z: emit.z,
      vx: worldVel.x,
      vy: worldVel.y,
      vz: worldVel.z,
      life: life,
      size: size,
      alpha: alpha,
      gravity: gravity,
      grow: grow
    };
    field.colors[i * 3] = color.r;
    field.colors[i * 3 + 1] = color.g;
    field.colors[i * 3 + 2] = color.b;
  }
  return field;
}

function makeFlashField(count) {
  const field = makeParticleField(count, THREE.AdditiveBlending);
  for (let i = 0; i < count; i++) {
    const local = new THREE.Vector3(0.5 + rng() * 10, 0.8 + rng() * 5, -32 + rng() * 64);
    const world = grandstand.localToWorld(local.clone());
    field.particles[i] = {
      t0: 36.49 + rng() * 3.4,
      x: world.x,
      y: world.y,
      z: world.z,
      vx: 0,
      vy: 0,
      vz: 0,
      life: 0.12 + rng() * 0.18,
      size: 0.35 + rng() * 0.6,
      alpha: 0.8,
      gravity: 0,
      grow: 1.5
    };
    field.colors[i * 3] = 1.0;
    field.colors[i * 3 + 1] = 1.0;
    field.colors[i * 3 + 2] = 1.0;
  }
  return field;
}

function updateParticleField(field, t) {
  const pos = field.positions;
  const sizes = field.sizes;
  const alphas = field.alphas;
  for (let i = 0; i < field.count; i++) {
    const p = field.particles[i];
    const age = t - p.t0;
    if (!p || age < 0 || age > p.life) {
      alphas[i] = 0;
      sizes[i] = 0;
      continue;
    }
    const k = age / p.life;
    const windX = p.windX || 0;
    const windY = p.windY || 0;
    const windZ = p.windZ || 0;
    const x = p.x + p.vx * age + windX * age;
    const y = p.y + p.vy * age + 0.5 * p.gravity * age * age + windY * age;
    const z = p.z + p.vz * age + windZ * age;
    const fadeIn = Math.min(1, k * 6);
    const fadeOut = 1 - k;
    alphas[i] = p.alpha * fadeIn * fadeOut;
    sizes[i] = p.size * (1 + p.grow * k);
    pos[i * 3] = x;
    pos[i * 3 + 1] = y;
    pos[i * 3 + 2] = z;
  }
  field.geo.attributes.position.needsUpdate = true;
  field.geo.attributes.aSize.needsUpdate = true;
  field.geo.attributes.aAlpha.needsUpdate = true;
}

function updateParticles(t) {
  for (let i = 0; i < particleFields.length; i++) {
    updateParticleField(particleFields[i], t);
  }
}

function createParticleFields() {
  particleFields = [];
  particleFields.push(makeCarParticleField(red, 'spray', 450));
  particleFields.push(makeCarParticleField(red, 'smoke', 350));
  particleFields.push(makeCarParticleField(red, 'sparks', 350));
  particleFields.push(makeCarParticleField(red, 'shimmer', 80));
  particleFields.push(makeCarParticleField(red, 'puff', 100));

  particleFields.push(makeCarParticleField(blue, 'spray', 450));
  particleFields.push(makeCarParticleField(blue, 'smoke', 350));
  particleFields.push(makeCarParticleField(blue, 'sparks', 350));
  particleFields.push(makeCarParticleField(blue, 'shimmer', 80));

  const flash = makeFlashField(140);
  particleFields.push(flash);
  flashTimes = flash.particles.map(function(p) { return p.t0; }).sort(function(a, b) { return a - b; });
}

function renderAt(t) {
  const redState = getCarState(red, t);
  const blueState = getCarState(blue, t);
  updateCarVisual(red, redState, t);
  updateCarVisual(blue, blueState, t);
  const mid = redState.pos.clone().add(blueState.pos).multiplyScalar(0.5);
  updateCamera(t, redState, blueState, mid);
  updateLights(mid);
  updateGantry(t);
  updateParticles(t);
  skyMat.uniforms.uTime.value = t;
  renderer.render(scene, camera);
}

let audioCtx = null;
let masterGain = null;
let compressor = null;
let audioReady = false;
let noiseBuffer = null;
let carAudio = [];
let oneShots = [];
let crowdGain = null;
let crowdPanner = null;
let breezeGain = null;
let floodGain = null;
let lastEventTime = 0;

function makeNoiseBuffer(seconds) {
  const rate = audioCtx.sampleRate;
  const len = Math.floor(rate * seconds);
  const buf = audioCtx.createBuffer(1, len, rate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < len; i++) data[i] = audioRng() * 2 - 1;
  return buf;
}

function createCarAudio(car) {
  const panner = audioCtx.createPanner();
  panner.panningModel = 'HRTF';
  panner.distanceModel = 'inverse';
  panner.refDistance = 6;
  panner.maxDistance = 300;
  panner.rolloffFactor = 1.2;
  panner.connect(masterGain);

  const engineGain = audioCtx.createGain();
  engineGain.gain.value = 0;
  engineGain.connect(panner);

  const engineFilter = audioCtx.createBiquadFilter();
  engineFilter.type = 'lowpass';
  engineFilter.frequency.value = 1800;
  engineFilter.Q.value = 0.7;
  engineFilter.connect(engineGain);

  const oscs = [];
  const harmonics = isBlue ? [
    { h: 1, g: 0.46, type: 'sawtooth' },
    { h: 2, g: 0.30, type: 'square' },
    { h: 3, g: 0.10, type: 'sawtooth' },
    { h: 0.5, g: 0.40, type: 'sawtooth' }
  ] : [
    { h: 1, g: 0.50, type: 'sawtooth' },
    { h: 2, g: 0.24, type: 'square' },
    { h: 3, g: 0.16, type: 'sawtooth' },
    { h: 0.5, g: 0.32, type: 'sawtooth' }
  ];

  for (let i = 0; i < harmonics.length; i++) {
    const h = harmonics[i];
    const osc = audioCtx.createOscillator();
    osc.type = h.type;
    osc.frequency.value = 120;
    const g = audioCtx.createGain();
    g.gain.value = h.g;
    osc.connect(g);
    g.connect(engineFilter);
    osc.start();
    oscs.push({ osc: osc, g: g, h: h.h });
  }

  const noise = audioCtx.createBufferSource();
  noise.buffer = noiseBuffer;
  noise.loop = true;
  const noiseFilter = audioCtx.createBiquadFilter();
  noiseFilter.type = 'bandpass';
  noiseFilter.frequency.value = 700;
  noiseFilter.Q.value = 1.0;
  const noiseGain = audioCtx.createGain();
  noiseGain.gain.value = 0.0;
  noise.connect(noiseFilter);
  noiseFilter.connect(noiseGain);
  noiseGain.connect(engineFilter);
  noise.start();

  const turbo = audioCtx.createOscillator();
  turbo.type = 'sine';
  turbo.frequency.value = 1200;
  const turboGain = audioCtx.createGain();
  turboGain.gain.value = 0;
  turbo.connect(turboGain);
  turboGain.connect(engineGain);
  turbo.start();

  const hiss = audioCtx.createBufferSource();
  hiss.buffer = noiseBuffer;
  hiss.loop = true;
  const hissFilter = audioCtx.createBiquadFilter();
  hissFilter.type = 'highpass';
  hissFilter.frequency.value = 1800;
  const hissGain = audioCtx.createGain();
  hissGain.gain.value = 0;
  hiss.connect(hissFilter);
  hissFilter.connect(hissGain);
  hissGain.connect(panner);
  hiss.start();

  const spin = audioCtx.createBufferSource();
  spin.buffer = noiseBuffer;
  spin.loop = true;
  const spinFilter = audioCtx.createBiquadFilter();
  spinFilter.type = 'bandpass';
  spinFilter.frequency.value = 2200;
  spinFilter.Q.value = 2.0;
  const spinGain = audioCtx.createGain();
  spinGain.gain.value = 0;
  spin.connect(spinFilter);
  spinFilter.connect(spinGain);
  spinGain.connect(panner);
  spin.start();

  const squealOsc = audioCtx.createOscillator();
  squealOsc.type = 'sine';
  squealOsc.frequency.value = 3200;
  const squealGain = audioCtx.createGain();
  squealGain.gain.value = 0;
  squealOsc.connect(squealGain);
  squealGain.connect(panner);
  squealOsc.start();

  const spark = audioCtx.createBufferSource();
  spark.buffer = noiseBuffer;
  spark.loop = true;
  const sparkFilter = audioCtx.createBiquadFilter();
  sparkFilter.type = 'highpass';
  sparkFilter.frequency.value = 4200;
  const sparkGain = audioCtx.createGain();
  sparkGain.gain.value = 0;
  spark.connect(sparkFilter);
  sparkFilter.connect(sparkGain);
  sparkGain.connect(panner);
  spark.start();

  const wind = audioCtx.createBufferSource();
  wind.buffer = noiseBuffer;
  wind.loop = true;
  const windFilter = audioCtx.createBiquadFilter();
  windFilter.type = 'lowpass';
  windFilter.frequency.value = 620;
  const windGain = audioCtx.createGain();
  windGain.gain.value = 0;
  wind.connect(windFilter);
  windFilter.connect(windGain);
  windGain.connect(panner);
  wind.start();

  return {
    car: car,
    panner: panner,
    engineGain: engineGain,
    engineFilter: engineFilter,
    oscs: oscs,
    noiseGain: noiseGain,
    turbo: turbo,
    turboGain: turboGain,
    hissGain: hissGain,
    spinGain: spinGain,
    squealGain: squealGain,
    sparkGain: sparkGain,
    windGain: windGain
  };
}

function createAmbientAudio() {
  crowdPanner = audioCtx.createPanner();
  crowdPanner.panningModel = 'HRTF';
  crowdPanner.distanceModel = 'inverse';
  crowdPanner.refDistance = 20;
  crowdPanner.maxDistance = 500;
  crowdPanner.rolloffFactor = 0.8;
  crowdPanner.connect(masterGain);

  const crowd = audioCtx.createBufferSource();
  crowd.buffer = noiseBuffer;
  crowd.loop = true;
  const crowdFilter = audioCtx.createBiquadFilter();
  crowdFilter.type = 'lowpass';
  crowdFilter.frequency.value = 480;
  crowdGain = audioCtx.createGain();
  crowdGain.gain.value = 0;
  crowd.connect(crowdFilter);
  crowdFilter.connect(crowdGain);
  crowdGain.connect(crowdPanner);
  crowd.start();

  const hum1 = audioCtx.createOscillator();
  hum1.type = 'sine';
  hum1.frequency.value = 60;
  const hum2 = audioCtx.createOscillator();
  hum2.type = 'sine';
  hum2.frequency.value = 120;
  floodGain = audioCtx.createGain();
  floodGain.gain.value = 0.003;
  hum1.connect(floodGain);
  hum2.connect(floodGain);
  floodGain.connect(masterGain);
  hum1.start();
  hum2.start();

  const breeze = audioCtx.createBufferSource();
  breeze.buffer = noiseBuffer;
  breeze.loop = true;
  const breezeFilter = audioCtx.createBiquadFilter();
  breezeFilter.type = 'highpass';
  breezeFilter.frequency.value = 900;
  breezeGain = audioCtx.createGain();
  breezeGain.gain.value = 0.008;
  breeze.connect(breezeFilter);
  breezeFilter.connect(breezeGain);
  breezeGain.connect(masterGain);
  breeze.start();
}

function initAudio() {
  if (audioCtx) return;
  const AC = window.AudioContext || window.webkitAudioContext;
  if (!AC) return;
  try {
    audioCtx = new AC();
  } catch (e) {
    return;
  }
  compressor = audioCtx.createDynamicsCompressor();
  compressor.threshold.value = -18;
  compressor.knee.value = 20;
  compressor.ratio.value = 8;
  compressor.attack.value = 0.003;
  compressor.release.value = 0.25;

  masterGain = audioCtx.createGain();
  masterGain.gain.value = 0;
  masterGain.connect(compressor);
  compressor.connect(audioCtx.destination);

  noiseBuffer = makeNoiseBuffer(2.0);
  carAudio = [createCarAudio(red), createCarAudio(blue)];
  createAmbientAudio();
  audioReady = true;

  if (audioCtx.state === 'suspended') {
    audioCtx.resume().catch(function() {});
  }
}

function resumeAudio() {
  if (audioCtx && audioCtx.state === 'suspended') {
    audioCtx.resume().catch(function() {});
  }
}

function setPannerPosition(p, v) {
  if (p.positionX) {
    p.positionX.value = v.x;
    p.positionY.value = v.y;
    p.positionZ.value = v.z;
  } else if (p.setPosition) {
    p.setPosition(v.x, v.y, v.z);
  }
}

function updateListener() {
  if (!audioCtx) return;
  const pos = camera.position;
  const fwd = new THREE.Vector3();
  camera.getWorldDirection(fwd);
  const up = new THREE.Vector3(0, 1, 0).applyQuaternion(camera.quaternion);
  const listener = audioCtx.listener;
  if (listener.positionX) {
    listener.positionX.value = pos.x;
    listener.positionY.value = pos.y;
    listener.positionZ.value = pos.z;
    listener.forwardX.value = fwd.x;
    listener.forwardY.value = fwd.y;
    listener.forwardZ.value = fwd.z;
    listener.upX.value = up.x;
    listener.upY.value = up.y;
    listener.upZ.value = up.z;
  } else if (listener.setPosition) {
    listener.setPosition(pos.x, pos.y, pos.z);
    listener.setOrientation(fwd.x, fwd.y, fwd.z, up.x, up.y, up.z);
  }
}

function addOneShot(source, gain) {
  const entry = { source: source, gain: gain };
  oneShots.push(entry);
  source.onended = function() {
    const idx = oneShots.indexOf(entry);
    if (idx >= 0) oneShots.splice(idx, 1);
  };
}

function stopAllOneShots() {
  if (!audioCtx) return;
  const now = audioCtx.currentTime;
  for (let i = 0; i < oneShots.length; i++) {
    const o = oneShots[i];
    try {
      o.gain.gain.cancelScheduledValues(now);
      o.gain.gain.setTargetAtTime(0.0001, now, 0.005);
      o.source.stop(now + 0.02);
    } catch (e) {}
  }
  oneShots.length = 0;
}

function playBeep(freq, dur, vol) {
  if (!audioReady) return;
  const now = audioCtx.currentTime;
  const osc = audioCtx.createOscillator();
  const g = audioCtx.createGain();
  osc.type = 'square';
  osc.frequency.value = freq;
  g.gain.setValueAtTime(0.0001, now);
  g.gain.exponentialRampToValueAtTime(vol, now + 0.005);
  g.gain.exponentialRampToValueAtTime(0.0001, now + dur);
  osc.connect(g);
  g.connect(masterGain);
  osc.start(now);
  osc.stop(now + dur + 0.02);
  addOneShot(osc, g);
}

function playClick(vol, dur, freq) {
  if (!audioReady) return;
  const now = audioCtx.currentTime;
  const src = audioCtx.createBufferSource();
  src.buffer = noiseBuffer;
  const filter = audioCtx.createBiquadFilter();
  filter.type = 'highpass';
  filter.frequency.value = freq;
  const g = audioCtx.createGain();
  g.gain.setValueAtTime(vol, now);
  g.gain.exponentialRampToValueAtTime(0.0001, now + dur);
  src.connect(filter);
  filter.connect(g);
  g.connect(masterGain);
  src.start(now);
  src.stop(now + dur + 0.02);
  addOneShot(src, g);
}

function playRoar() {
  if (!audioReady) return;
  const now = audioCtx.currentTime;
  const src = audioCtx.createBufferSource();
  src.buffer = noiseBuffer;
  src.loop = true;
  const filter = audioCtx.createBiquadFilter();
  filter.type = 'lowpass';
  filter.frequency.value = 650;
  const g = audioCtx.createGain();
  g.gain.setValueAtTime(0.0001, now);
  g.gain.exponentialRampToValueAtTime(0.08, now + 0.4);
  g.gain.exponentialRampToValueAtTime(0.0001, now + 2.5);
  src.connect(filter);
  filter.connect(g);
  g.connect(masterGain);
  src.start(now);
  src.stop(now + 2.6);
  addOneShot(src, g);
}

function getEngineState(st, t) {
  const speed = Math.max(0, st.speed);
  const gear = Math.min(7, Math.floor(speed / 8.5));
  const within = clamp((speed - gear * 8.5) / 8.5, 0, 1);
  let rpm = 5000 + within * 7000;
  let idleWobble = 0;
  if (t < 3 || speed < 2) {
    rpm = 5000 + Math.sin(t * Math.PI * 2 * 2) * 150;
    idleWobble = Math.sin(t * Math.PI * 2 * 2) * 40;
  }
  return { rpm: rpm, gear: gear, within: within, idleWobble: idleWobble };
}

function updateAudio(t, state) {
  if (!audioReady) return;
  const now = audioCtx.currentTime;
  const playing = state === 'PLAYING';
  masterGain.gain.setTargetAtTime(playing ? 0.9 : 0, now, 0.015);
  if (!playing) stopAllOneShots();

  updateListener();

  for (let i = 0; i < carAudio.length; i++) {
    const ca = carAudio[i];
    const car = ca.car;
    const st = getCarState(car, t);
    setPannerPosition(ca.panner, st.pos);

    const toCar = st.pos.clone().sub(camera.position);
    const dist = toCar.length();
    toCar.normalize();
    const carVel = st.forward.clone().multiplyScalar(st.speed);
    const radial = carVel.dot(toCar);
    const doppler = clamp(1 - radial / 343, 0.7, 1.3);

    const eng = getEngineState(st, t);
    const firing = eng.rpm / 60 * 3 * doppler + eng.idleWobble;
    for (let k = 0; k < ca.oscs.length; k++) {
      const o = ca.oscs[k];
      o.osc.frequency.setTargetAtTime(firing * o.h, now, 0.03);
    }

    const throttle = clamp(0.25 + st.accel / 25, 0, 1);
    const isOnboardBlue = (car.isBlue && t >= 15 && t < 20);
    let vol = (0.035 + 0.08 * throttle) * (0.8 + 0.2 * Math.sin(Math.PI * eng.within));
    if (isOnboardBlue) vol *= 2.0;
    ca.engineGain.gain.setTargetAtTime(vol, now, 0.03);
    ca.engineFilter.frequency.setTargetAtTime(isOnboardBlue ? 900 : 1200 + st.speed * 25, now, 0.05);
    ca.noiseGain.gain.setTargetAtTime(0.02 + 0.04 * clamp(st.speed / 70, 0, 1), now, 0.05);
